import { createRouter, createWebHistory } from 'vue-router'
import DashboardPage from '../views/DashboardPage.vue'
import OpenPositionsPage from '../views/OpenPositionsPage.vue'
import LoginPage from '../views/LoginPage.vue'
import RegisterPage from '../views/RegisterPage.vue'
import ProfileLayout from '../components/ProfileLayout.vue'
import Profile from '../components/Profile.vue'
import ProfileEdit from '../components/ProfileEdit.vue'
import ProfileSettings from '../components/ProfileSettings.vue'
import store from '../store'
import ClosedPositions from '../views/ClosedPositionsPage.vue'

const routes = [
  {
    path: '/login',
    name: 'Login',
    component: LoginPage,
    meta: { requiresAuth: false }
  },
  {
    path: '/register',
    name: 'Register',
    component: RegisterPage,
    meta: { requiresAuth: false }
  },
  {
    path: '/dashboard',
    name: 'Dashboard',
    component: DashboardPage,
    meta: { requiresAuth: true }
  },
  {
    path: '/open-positions',
    name: 'OpenPositions',
    component: OpenPositionsPage,
    meta: { requiresAuth: true }
  },
  {
    path: '/profile',
    component: ProfileLayout,
    meta: { requiresAuth: true },
    children: [
      {
        path: '',
        name: 'Profile',
        component: Profile
      },
      {
        path: 'edit',
        name: 'ProfileEdit',
        component: ProfileEdit
      },
      {
        path: 'settings',
        name: 'ProfileSettings',
        component: ProfileSettings
      }
    ]
  },
  {
    path: '/closed-positions',
    name: 'ClosedPositions',
    component: ClosedPositions,
    meta: { requiresAuth: true }
  },
  // {
  //   path: '/database',
  //   name: 'Database',
  //   component: () => import('../views/DatabasePage.vue'),
  //   meta: { requiresAuth: true },
  //   children: [
  //     {
  //       path: 'brokers',
  //       name: 'Brokers',
  //       component: () => import('../views/database/BrokersPage.vue'),
  //     },
  //     {
  //       path: 'securities',
  //       name: 'Securities',
  //       component: () => import('../views/database/SecuritiesPage.vue'),
  //     },
  //     {
  //       path: 'prices',
  //       name: 'Prices',
  //       component: () => import('../views/database/PricesPage.vue'),
  //     },
  //   ]
  // },
  {
    path: '/',
    redirect: '/dashboard'
  }
]

const router = createRouter({
  history: createWebHistory(process.env.BASE_URL),
  routes
})

router.beforeEach((to, from, next) => {
  const isAuthenticated = !!localStorage.getItem('token');
  
  if (to.meta.requiresAuth && !isAuthenticated) {
    next('/login');
  } else if (to.path === '/login' && isAuthenticated) {
    next('/dashboard');
  } else {
    if (!to.meta.requiresAuth) {
      store.dispatch('updatePageTitle', '')
    }
    next()
  }
})

export default router
